questionvariables.text:
/* y = sin(x - c) or y = cos(x - c) for 0 <= x <= 360 degrees (or 0 <= x <= 2*pi).
   un: 1 = degrees, 2 = radians; fs: 1 = sin, 2 = cos; c = +-30, +-60, +-90 degrees.
   2 x 2 x 6 = 24 distinct variants. */
un : rand([1, 2]);
fs : rand([1, 2]);
cdeg : rand([-90, -60, -30, 30, 60, 90]);
crad : cdeg*%pi/180;
dirc : if cdeg > 0 then 2 else 1;          /* 1 = left, 2 = right */
wdirc : 3 - dirc;                          /* the other direction (for testing) */
ddopts : [[1, is(dirc = 1), "to the left"], [2, is(dirc = 2), "to the right"]];
amt : if un = 1 then abs(cdeg) else abs(crad);
amtdeg : abs(cdeg);
/* the 13 x-values, every 30 degrees */
xsd : makelist(30*k, k, 0, 12);
xsr : makelist(k*%pi/6, k, 0, 12);
xsv : if un = 1 then xsd else xsr;
/* exact y-values, the y-values for the wrong shift direction, and decimals */
yex : if fs = 1 then makelist(sin((30*k - cdeg)*%pi/180), k, 0, 12) else makelist(cos((30*k - cdeg)*%pi/180), k, 0, 12);
yexw : if fs = 1 then makelist(sin((30*k + cdeg)*%pi/180), k, 0, 12) else makelist(cos((30*k + cdeg)*%pi/180), k, 0, 12);
yv : float(yex);
yvw : float(yexw);
yr : float(map(round, 100*yv)/100);              /* values to 2 decimal places */
yrw : float(map(round, 100*yvw)/100);
tb1 : yr[2];
tw1 : yrw[2];
tb2 : yr[5];
tw2 : yrw[5];
tb3 : yr[7];
tw3 : yrw[7];
tb4 : yr[9];
tw4 : yrw[9];
tb5 : yr[12];
tw5 : yrw[12];
/* worked example in the solution: x = 120 degrees (position 5) */
inner5d : 120 - cdeg;
inner5r : 2*%pi/3 - crad;

feedbackvariables.text:
/* within 0.011 of the exact value accepts 2 d.p. rounding and exact forms */
okv : is(abs(float(ans1) - yv[2]) <= 0.011);
wdir : is(abs(float(ans1) - yvw[2]) <= 0.011);

/* within 0.011 of the exact value accepts 2 d.p. rounding and exact forms */
okv : is(abs(float(ans2) - yv[5]) <= 0.011);
wdir : is(abs(float(ans2) - yvw[5]) <= 0.011);

/* within 0.011 of the exact value accepts 2 d.p. rounding and exact forms */
okv : is(abs(float(ans3) - yv[7]) <= 0.011);
wdir : is(abs(float(ans3) - yvw[7]) <= 0.011);

/* within 0.011 of the exact value accepts 2 d.p. rounding and exact forms */
okv : is(abs(float(ans4) - yv[9]) <= 0.011);
wdir : is(abs(float(ans4) - yvw[9]) <= 0.011);

/* within 0.011 of the exact value accepts 2 d.p. rounding and exact forms */
okv : is(abs(float(ans5) - yv[12]) <= 0.011);
wdir : is(abs(float(ans5) - yvw[12]) <= 0.011);

/* the 13 plotted y-values; anything else (not a list of 13) counts as no points correct */
gl : if listp(ansg) and length(ansg) = 13 then float(ansg) else makelist(100, k, 1, 13);
nok : sum(if abs(gl[k] - yv[k]) <= 0.1 then 1 else 0, k, 1, 13);
nwr : sum(if abs(gl[k] - yvw[k]) <= 0.1 then 1 else 0, k, 1, 13);
badx : delete(nix, makelist(if abs(gl[k] - yv[k]) > 0.1 then xsv[k] else nix, k, 1, 13));
